      },
    });
  }
}

async function searchContext(client: any, topic: string): Promise<string[]> {
  const result: any = await client.v1.context.search({
    query: topic,
    scope: 'internal',
    similarity_threshold: 0.8,
    minimum_similarity_threshold: 0.0,
    mode: 'standard',
  });

  const contexts: any[] =
    (Array.isArray(result?.contexts) && result.contexts) ||
    (Array.isArray(result?.data) && result.data) ||
    (Array.isArray(result?.results) && result.results) ||
    [];

  return contexts
    .map((c: any) => String(c.content ?? c.text ?? ''))
    .filter((s: string) => s.trim().length > 0);
}

async function generateNewsletter(topic: string, grounding: string): Promise<string> {
  const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

